const money=n=>n.toLocaleString('ko-KR')+'원';const cart=new Map();let slide=0,toastTimer;const $=s=>document.querySelector(s);const esc=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
$('#slides').innerHTML=catalog.slides.map((s,i)=>`<a class="slide ${i===0?'active':''}" href="${i===0?'#collection':esc(s.url)}" ${i?'target="_blank" rel="noopener"':''}><picture><source media="(max-width:600px)" srcset="${s.mobile}"><img src="${s.image}" alt="${['추석 와인 감사 선물세트','와인 대량 주문 및 맞춤 선물','1879 와인 기획전'][i]}" ${i?'loading="lazy"':'fetchpriority="high"'}></picture></a>`).join('');
function changeSlide(delta){slide=(slide+delta+catalog.slides.length)%catalog.slides.length;document.querySelectorAll('.slide').forEach((el,i)=>el.classList.toggle('active',i===slide));$('#slide-count').textContent=`0${slide+1} / 0${catalog.slides.length}`};$('#previous').onclick=()=>changeSlide(-1);$('#next').onclick=()=>changeSlide(1);
function renderProducts(){const q=$('#search').value.trim().toLowerCase();let list=catalog.products.filter(w=>w.name.toLowerCase().includes(q));if($('#sort').value==='low')list.sort((a,b)=>a.price-b.price);if($('#sort').value==='high')list.sort((a,b)=>b.price-a.price);$('#result-count').textContent=`전체 ${list.length}개 상품`;$('#products').innerHTML=list.map(w=>`<article class="product"><div class="product-image"><button data-detail="${w.id}" aria-label="${esc(w.name)} 상세 보기"><img src="${w.image}" alt="${esc(w.name)}" loading="lazy"></button><span class="discount">${Math.round((1-w.price/w.original)*100)}%</span></div><h2><button class="text-button" data-detail="${w.id}">${esc(w.name)}</button></h2><div class="price-row"><strong>${money(w.price)}</strong><del>${money(w.original)}</del></div><div class="product-actions"><span class="soldout">${w.soldout?'품절':'판매중'}</span><button class="add" data-add="${w.id}" aria-label="${esc(w.name)} 미리보기 목록 담기">목록 담기 +</button></div></article>`).join('')||'<p class="empty">검색 결과가 없습니다. 다른 상품명으로 검색해 주세요.</p>'};$('#search').oninput=renderProducts;$('#sort').onchange=renderProducts;renderProducts();
$('#services').innerHTML=catalog.services.map((s,i)=>`<a href="${esc(s.url)}" target="_blank" rel="noopener"><img src="${s.image}" alt="${['기프트 케어 서비스','와인 선물 서비스','고객 서비스 안내'][i]}" loading="lazy"><span class="service-link">${['기프트 케어','와인 선물 서비스','서비스 안내'][i]}<span>자세히 보기 ↗</span></span></a>`).join('');
function renderCart(){let total=0,count=0;$('#cart-items').innerHTML=[...cart].map(([id,qty])=>{const w=catalog.products.find(w=>w.id===id);total+=w.price*qty;count+=qty;return `<div class="cart-item"><img src="${w.image}" alt=""><div class="info"><strong>${esc(w.name)}</strong><small>${money(w.price)} · ${w.soldout?'품절':'판매중'}</small></div><div class="quantity"><button data-change="${id}" data-delta="-1" aria-label="${esc(w.name)} 수량 줄이기">−</button><span>${qty}</span><button data-change="${id}" data-delta="1" aria-label="${esc(w.name)} 수량 늘리기">+</button></div></div>`}).join('')||'<p class="empty">담긴 상품이 없습니다.<br>관심 있는 상품을 목록에 담아보세요.</p>';$('#count').textContent=count;$('#total').textContent=money(total);$('#export').disabled=!count}
function add(id){cart.set(id,(cart.get(id)||0)+1);renderCart();$('#toast').textContent='미리보기 목록에 담았습니다. 주문은 접수되지 않습니다.';$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',2800)}
function detail(id){const w=catalog.products.find(w=>w.id===id);$('#detail-body').innerHTML=`<div class="detail-layout"><img src="${w.image}" alt="${esc(w.name)}"><div><span class="soldout">${w.soldout?'품절':'판매중'}</span><h2>${esc(w.name)}</h2><div class="price-row"><strong>${money(w.price)}</strong><del>${money(w.original)}</del></div><p class="detail-note">2026.09.13 원본 사이트 확인 기준<br>가격 및 재고는 변경될 수 있습니다.</p><a class="primary" href="${esc(w.url)}" target="_blank" rel="noopener">원본 상품 정보 확인 ↗</a><button class="outline" data-add="${w.id}">미리보기 목록 담기 +</button><p class="detail-note">실제 주문 및 결제 기능은 제공하지 않습니다.</p></div></div>`;$('#detail').showModal()}
for(const selector of ['#products','#detail-body'])$(selector).addEventListener('click',e=>{const b=e.target.closest('[data-add],[data-detail]');if(!b)return;if(b.dataset.add)add(Number(b.dataset.add));else detail(Number(b.dataset.detail))});
$('#cart-items').addEventListener('click',e=>{const b=e.target.closest('[data-change]');if(!b)return;const id=Number(b.dataset.change),qty=(cart.get(id)||0)+Number(b.dataset.delta);qty<=0?cart.delete(id):cart.set(id,qty);renderCart()});$('#open-cart').onclick=()=>{renderCart();$('#cart').showModal()};document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$('#'+b.dataset.close).close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
$('#menu-toggle').onclick=()=>{const open=$('#nav').classList.toggle('expanded');$('#menu-toggle').setAttribute('aria-expanded',String(open));$('#nav').scrollIntoView({block:'nearest'})};$('#search-toggle').onclick=()=>{$('#collection').scrollIntoView();$('#search').focus({preventScroll:true})};
$('#export').onclick=()=>{let total=0;const lines=[...cart].map(([id,qty])=>{const w=catalog.products.find(w=>w.id===id);total+=w.price*qty;return `${w.name} × ${qty}: ${money(w.price*qty)} (품절)\n${w.url}`});const blob=new Blob(['\uFEFF1879 와인 상품 목록\n\n'+lines.join('\n\n')+'\n\n합계: '+money(total)+'\n확인일: 2026.09.13\n미리보기용 목록이며 주문이나 결제가 접수되지 않았습니다.'],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='1879-wine-list.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};renderCart();
